/*============================================================================
GRAMMAR PROGRESS: {correct, incorrect} PER-ENDING TRACKING
Mirrors the vocab progress schema in vocab/vocabData.js (see
normalizeWordProgressEntry/isWordLearned/isWeakWord there). Each ending's
entry used to be a plain boolean (true/false) recording only whether it had
ever been marked completed. It's now an object counting every attempt.
============================================================================*/

function normalizeGrammarProgressEntry(entry) {
    if (entry && typeof entry === "object") {
        return {
            correct: Number(entry.correct) || 0,
            incorrect: Number(entry.incorrect) || 0
        };
    }

    // Migrate the legacy boolean format: true meant "marked completed".
    if (entry === true) {
        return { correct: 1, incorrect: 0 };
    }

    return { correct: 0, incorrect: 0 };
}

function isEndingLearned(entry) {
    return !!entry && entry.correct > 0;
}

function isWeakEnding(entry) {
    return !!entry && entry.incorrect > entry.correct;
}

let grammarProgress = {};
function buildGrammar(){
    let savedGrammarProgress = localStorage.getItem("latinGrammarProgress");
    if (savedGrammarProgress) {
        grammarProgress = JSON.parse(savedGrammarProgress);
    } else {
        grammarProgress = {};
    }

    grammarData.forEach(word => {
        const key = "i" + word.index;

        grammarProgress[key] = normalizeGrammarProgressEntry(grammarProgress[key]);
    });

    // Save it back to local storage just to keep it clean
    localStorage.setItem("latinGrammarProgress", JSON.stringify(grammarProgress));
}
buildGrammar();